insert into public.questions (id, kind, prompt, options, marks, image_url) values ('d2952032-09f3-504e-a958-1c20338d7b40', 'short', 'Explain why bright colouration persists in male guppies despite increasing predation risk.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Trinidadian_guppy_(Poecilia_reticulata)_male_and_female.png?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d2952032-09f3-504e-a958-1c20338d7b40', 'Females prefer to mate with brightly coloured males [1], so bright males produce more offspring and pass on their alleles, even if they are more likely to be eaten (sexual selection) [1].', 'Females prefer to mate with brightly coloured males [1], so bright males produce more offspring and pass on their alleles, even if they are more likely to be eaten (sexual selection) [1].', '[{"text": "Marking point 1", "any": ["female", "mate", "prefer", "choose"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["more offspring", "reproduce", "pass on", "sexual selection"], "all": [], "marks": 1}]'::jsonb, 'Females prefer to mate with brightly coloured males [1], so bright males produce more offspring and pass on their alleles, even if they are more likely to be eaten (sexual selection) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0f1fac03-90af-57c2-86ca-ec5eed47923c', 'd2952032-09f3-504e-a958-1c20338d7b40', 12);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('46ed6427-3e6c-5169-8b5c-239272690313', 'short', 'Explain how natural selection could lead to antibiotic resistance in bacteria.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('46ed6427-3e6c-5169-8b5c-239272690313', 'A mutation gives some bacteria resistance [1]; the antibiotic kills non-resistant bacteria while resistant ones survive [1]; survivors reproduce and pass on the resistance allele, so its frequency increases [1].', 'A mutation gives some bacteria resistance [1]; the antibiotic kills non-resistant bacteria while resistant ones survive [1]; survivors reproduce and pass on the resistance allele, so its frequency increases [1].', '[{"text": "Marking point 1", "any": ["mutation", "variation", "resistant"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["survive", "selection pressure"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["reproduce", "pass on", "allele frequency", "increase"], "all": [], "marks": 1}]'::jsonb, 'A mutation gives some bacteria resistance [1]; the antibiotic kills non-resistant bacteria while resistant ones survive [1]; survivors reproduce and pass on the resistance allele, so its frequency increases [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0f1fac03-90af-57c2-86ca-ec5eed47923c', '46ed6427-3e6c-5169-8b5c-239272690313', 13);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('7c581686-2466-5985-8d56-3e3cf9dea8cc', 'short', 'Explain why allele frequencies differ between geographically isolated populations of the same species.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('7c581686-2466-5985-8d56-3e3cf9dea8cc', 'There is no interbreeding (gene flow) between the populations [1]; they experience different selection pressures, mutations and genetic drift, so allele frequencies change independently [1].', 'There is no interbreeding (gene flow) between the populations [1]; they experience different selection pressures, mutations and genetic drift, so allele frequencies change independently [1].', '[{"text": "Marking point 1", "any": ["gene flow", "interbreed", "separate gene pool", "isolated"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["different selection", "different environment", "drift", "mutation"], "all": [], "marks": 1}]'::jsonb, 'There is no interbreeding (gene flow) between the populations [1]; they experience different selection pressures, mutations and genetic drift, so allele frequencies change independently [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0f1fac03-90af-57c2-86ca-ec5eed47923c', '7c581686-2466-5985-8d56-3e3cf9dea8cc', 14);
