insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('42a4c4c8-d5a2-5b26-8e40-b99aa4d2242e', 'Acquired characteristics are not caused by alleles and do not alter DNA in the gametes [1], so they are not passed on to offspring and cannot change allele frequencies [1].', 'Acquired characteristics are not caused by alleles and do not alter DNA in the gametes [1], so they are not passed on to offspring and cannot change allele frequencies [1].', '[{"text": "Marking point 1", "any": ["not genetic", "dna", "alleles", "not inherited"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["gametes", "offspring", "not passed"], "all": [], "marks": 1}]'::jsonb, 'Acquired characteristics are not caused by alleles and do not alter DNA in the gametes [1], so they are not passed on to offspring and cannot change allele frequencies [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
