insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('46ed6427-3e6c-5169-8b5c-239272690313', 'A mutation gives some bacteria resistance [1]; the antibiotic kills non-resistant bacteria while resistant ones survive [1]; survivors reproduce and pass on the resistance allele, so its frequency increases [1].', 'A mutation gives some bacteria resistance [1]; the antibiotic kills non-resistant bacteria while resistant ones survive [1]; survivors reproduce and pass on the resistance allele, so its frequency increases [1].', '[{"text": "Marking point 1", "any": ["mutation", "variation", "resistant"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["survive", "selection pressure"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["reproduce", "pass on", "allele frequency", "increase"], "all": [], "marks": 1}]'::jsonb, 'A mutation gives some bacteria resistance [1]; the antibiotic kills non-resistant bacteria while resistant ones survive [1]; survivors reproduce and pass on the resistance allele, so its frequency increases [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
