insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e44fb00b-75ed-5475-bd82-3f8f8f2c90a7', 'Two species cross to form a (usually sterile) hybrid [1]; chromosome doubling makes it polyploid, so each chromosome has a partner and meiosis works [1]; it is fertile with similar polyploids but reproductively isolated from the parent species, so it is a new species [1].', 'Two species cross to form a (usually sterile) hybrid [1]; chromosome doubling makes it polyploid, so each chromosome has a partner and meiosis works [1]; it is fertile with similar polyploids but reproductively isolated from the parent species, so it is a new species [1].', '[{"text": "Marking point 1", "any": ["hybrid", "two species"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["doubl", "polyploid", "chromosome number"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["cannot breed with", "reproductively isolated", "isolated", "sterile with parent", "new species"], "all": [], "marks": 1}]'::jsonb, 'Two species cross to form a (usually sterile) hybrid [1]; chromosome doubling makes it polyploid, so each chromosome has a partner and meiosis works [1]; it is fertile with similar polyploids but reproductively isolated from the parent species, so it is a new species [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
