insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('1cf75dde-aad6-503d-94d7-21b2c2025c51', 'DDT is not broken down or excreted and is stored in fat [1]; each consumer eats many organisms from the level below, so DDT accumulates [1]; concentration increases at each trophic level and is highest in top predators (biomagnification) [1].', 'DDT is not broken down or excreted and is stored in fat [1]; each consumer eats many organisms from the level below, so DDT accumulates [1]; concentration increases at each trophic level and is highest in top predators (biomagnification) [1].', '[{"text": "Marking point 1", "any": ["not broken down", "not excreted", "persist", "fat"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["eat many", "accumulates", "each trophic level"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["highest concentration", "top", "biomagnif"], "all": [], "marks": 1}]'::jsonb, 'DDT is not broken down or excreted and is stored in fat [1]; each consumer eats many organisms from the level below, so DDT accumulates [1]; concentration increases at each trophic level and is highest in top predators (biomagnification) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
